<script setup lang="ts">
import { registerChordListFile } from '../../../../src/engraving/dom/chordlist'
import { pickFile } from '../../../files'
import { qtrc, useLanguage } from '../../../i18n'
import { ICON_CODES } from '../../../actions/uiactiondata'
import ChordNumber from './ChordNumber.vue'
import {
  GroupBox,
  LineStyleSection,
  RadioButtonSelectorWithReset,
  StyleSpinboxWithReset,
  StyleToggle,
  TextFieldWithReset,
  type NotationStyleLike,
} from './controls.vue'

const props = defineProps<{
  score?: any
  style: NotationStyleLike
  goToTextStylePage?: (codeOrIndex: string | number) => void
}>()

useLanguage()
async function selectPreset(event: Event) {
  const value = Number((event.target as HTMLSelectElement).value)
  if (value !== 3) {
    props.style.setValue('chordDescriptionFile', ['chords_std.xml', 'chords_jazz.xml', 'chords_legacy.xml'][value])
    if (value === 2) props.style.setValue('chordBassNoteStagger', false)
  }
  props.style.setValue('chordStyle', value)
}
async function loadCustom() {
  const file = await pickFile({ description: 'Chord description XML', accept: { 'application/xml': ['.xml'] } })
  if (!file) return
  registerChordListFile(file.name, await file.text())
  props.style.setValue('chordDescriptionFile', file.name)
}
</script>

<template>
  <div class="sd-column" style="gap:12px">
    <fieldset class="sd-groupbox" style="min-width:500px"><legend>{{ qtrc('notation/editstyle/chordsymbols','Preset') }}</legend><div class="sd-column" style="gap:12px"><div style="min-width:192px"><select class="sd-dropdown" :aria-label="qtrc('notation/editstyle/chordsymbols','Preset')" :value="style.value('chordStyle')" @change="selectPreset"><option v-for="(label,value) in ['Standard','Jazz','Legacy MuseScore','Load custom XML…']" :key="value" :value="value">{{ qtrc('notation/editstyle/chordsymbols',label) }}</option></select></div><div v-if="style.value('chordStyle')===3" class="sd-row" style="gap:8px"><input class="sd-text" style="width:138px" disabled :value="style.value('chordDescriptionFile')"><button type="button" class="sd-flat-button icon-only" :aria-label="qtrc('notation','Load style')" @click="loadCustom"><span class="sd-icon">{{ String.fromCodePoint(ICON_CODES.OPEN_FILE) }}</span></button></div></div></fieldset>
    <fieldset class="sd-groupbox" style="min-width:500px"><legend>{{ qtrc('notation/editstyle/chordsymbols','Appearance') }}</legend><div class="sd-column" style="gap:12px">
      <div><button type="button" class="sd-flat-button" @click="goToTextStylePage?.('chord-symbols')">{{ qtrc('notation','Edit chord symbol text style') }}</button></div>
      <fieldset class="sd-groupbox"><legend>{{ qtrc('notation/editstyle/chordsymbols','Spelling') }}</legend><div class="sd-column" style="gap:12px"><div class="sd-row" style="gap:12px"><label v-for="(label,index) in ['Standard','German','Full German','Solfeggio','French']" :key="label" class="sd-radio"><input type="radio" name="chord-spelling" :checked="style.value('chordSymbolSpelling')===index" @change="style.setValue('chordSymbolSpelling',index)"><span>{{ qtrc('notation/editstyle/chordsymbols',label) }}</span></label><button type="button" class="sd-flat-button icon-only" :aria-label="qtrc('global','Reset')" @click="style.resetValue?.('chordSymbolSpelling')"><span class="sd-icon">{{ String.fromCodePoint(ICON_CODES.UNDO) }}</span></button></div></div></fieldset>
      <fieldset class="sd-groupbox"><legend>{{ qtrc('notation/editstyle/chordsymbols','Capitalization') }}</legend><div class="sd-column" style="gap:12px"><div class="sd-row" style="gap:8px"><label class="sd-toggle"><input type="checkbox" role="switch" :checked="style.value('automaticCapitalization')===true" @change="style.setValue('automaticCapitalization',!style.value('automaticCapitalization'))"><span class="sd-toggle-track" aria-hidden="true"></span><span>{{ qtrc('notation/editstyle/chordsymbols','Automatically capitalize note names') }}</span></label><button type="button" class="sd-flat-button icon-only" :aria-label="qtrc('global','Reset')" @click="['automaticCapitalization','lowerCaseMinorChords','lowerCaseBassNotes','allCapsNoteNames'].forEach(id=>style.resetValue?.(id))"><span class="sd-icon">{{ String.fromCodePoint(ICON_CODES.UNDO) }}</span></button></div><div class="sd-column" style="gap:8px"><label v-for="item in [{id:'lowerCaseMinorChords',label:'Lowercase minor chords'},{id:'lowerCaseBassNotes',label:'Lowercase bass notes'},{id:'allCapsNoteNames',label:'All caps (for Solfeggio and French)'}]" :key="item.id" class="sd-checkbox" :class="{disabled:!style.value('automaticCapitalization') || (item.id==='allCapsNoteNames' && ![3,4].includes(Number(style.value('chordSymbolSpelling'))))}"><input type="checkbox" :disabled="!style.value('automaticCapitalization') || (item.id==='allCapsNoteNames' && ![3,4].includes(Number(style.value('chordSymbolSpelling'))))" :checked="style.value(item.id)===true" @change="style.setValue(item.id,!style.value(item.id))"><span>{{ qtrc('notation/editstyle/chordsymbols',item.label) }}</span></label></div></div></fieldset>
      <fieldset v-for="group in [{title:'Extensions (e.g. 7, 11)',ids:['chordExtensionMag','chordExtensionAdjust']},{title:'Modifiers (e.g. sus4, no 3)',ids:['chordModifierMag','chordModifierAdjust']}]" :key="group.title" class="sd-groupbox"><legend>{{ qtrc('notation/editstyle/chordsymbols',group.title) }}</legend><div class="sd-column" style="gap:12px"><div v-for="(id,index) in group.ids" :key="id" class="sd-row" style="gap:6px"><span class="sd-label">{{ qtrc('notation',index===0?'Scale:':'Vertical offset:') }}</span><ChordNumber :style-model="style" :id="id" :label="qtrc('notation',index===0?'Scale:':'Vertical offset:')" :min="index===0?0:-999" percent /><button v-if="index===0" type="button" class="sd-flat-button icon-only" :aria-label="qtrc('global','Reset')" @click="group.ids.forEach(key=>style.resetValue?.(key))"><span class="sd-icon">{{ String.fromCodePoint(ICON_CODES.UNDO) }}</span></button></div><label v-if="group.title.startsWith('Modifiers')" class="sd-checkbox"><input type="checkbox" :checked="style.value('verticallyStackModifiers')===true" @change="style.setValue('verticallyStackModifiers',!style.value('verticallyStackModifiers'))"><span>{{ qtrc('notation/editstyle/chordsymbols','Vertically stack modifiers') }}</span></label></div></fieldset>
      <fieldset class="sd-groupbox"><legend>{{ qtrc('notation/editstyle/chordsymbols','Altered bass notes (e.g. A7/G)') }}</legend><div class="sd-column" style="gap:12px"><div class="sd-row" style="gap:6px"><span class="sd-label">{{ qtrc('notation','Style:') }}</span><div class="sd-flat-radio-group" role="radiogroup" style="gap:4px"><button v-for="(icon,index) in [ICON_CODES.CHORD_BASS_ALIGN,ICON_CODES.CHORD_BASS_OFFSET]" :key="index" type="button" role="radio" class="sd-flat-radio" style="width:48px;height:48px;flex:0 0 auto" :disabled="style.value('chordStyle')===2" :aria-checked="style.value('chordBassNoteStagger')===(index===1)" @click="style.setValue('chordBassNoteStagger',index===1)"><span class="sd-icon" aria-hidden="true">{{ String.fromCodePoint(icon) }}</span></button></div><button type="button" class="sd-flat-button icon-only" :aria-label="qtrc('global','Reset')" @click="['chordBassNoteStagger','chordBassNoteScale'].forEach(id=>style.resetValue?.(id))"><span class="sd-icon">{{ String.fromCodePoint(ICON_CODES.UNDO) }}</span></button></div><div class="sd-row" style="gap:6px"><span class="sd-label">{{ qtrc('notation','Bass note scale:') }}</span><ChordNumber :style-model="style" id="chordBassNoteScale" :label="qtrc('notation','Bass note scale:')" percent /></div></div></fieldset>
      <fieldset class="sd-groupbox"><legend>{{ qtrc('notation/editstyle/chordsymbols','Polychords (e.g. C|F♯)') }}</legend><div class="sd-column" style="gap:12px"><div v-for="(item,index) in [{id:'polychordDividerThickness',label:'Divider thickness:'},{id:'polychordDividerSpacing',label:'Divider spacing:'}]" :key="item.id" class="sd-row" style="gap:6px"><span class="sd-label">{{ qtrc('notation',item.label) }}</span><ChordNumber :style-model="style" :id="item.id" :label="qtrc('notation',item.label)" /><button v-if="index===0" type="button" class="sd-flat-button icon-only" :aria-label="qtrc('global','Reset')" @click="['polychordDividerThickness','polychordDividerSpacing'].forEach(id=>style.resetValue?.(id))"><span class="sd-icon">{{ String.fromCodePoint(ICON_CODES.UNDO) }}</span></button></div></div></fieldset>
      <label class="sd-checkbox"><input type="checkbox" :checked="style.value('harmonyParenUseSmuflSym')===true" @change="style.setValue('harmonyParenUseSmuflSym',!style.value('harmonyParenUseSmuflSym'))"><span>{{ qtrc('notation/editstyle/chordsymbols','Use SMuFL symbols') }}</span></label>
    </div></fieldset>
    <fieldset class="sd-groupbox" style="min-width:500px"><legend>{{ qtrc('notation/editstyle/chordsymbols','Alignment') }}</legend><div class="sd-column" style="gap:12px"><div class="sd-row" style="gap:6px"><label class="sd-checkbox"><input type="checkbox" :checked="style.value('verticallyAlignChordSymbols')===true" @change="style.setValue('verticallyAlignChordSymbols',!style.value('verticallyAlignChordSymbols'))"><span>{{ qtrc('notation/editstyle/chordsymbols','Vertically align chord symbols and fretboard diagrams on the same system') }}</span></label><button type="button" class="sd-flat-button icon-only" :aria-label="qtrc('global','Reset')" @click="['verticallyAlignChordSymbols','chordSymPosition','chordAlignmentToFretboard','chordAlignmentExcludeModifiers'].forEach(id=>style.resetValue?.(id))"><span class="sd-icon">{{ String.fromCodePoint(ICON_CODES.UNDO) }}</span></button></div><div v-for="item in [{id:'chordSymPosition',label:'Alignment to notehead:',icons:[ICON_CODES.NOTE_ALIGN_LEFT,ICON_CODES.NOTE_ALIGN_CENTER,ICON_CODES.NOTE_ALIGN_RIGHT]},{id:'chordAlignmentToFretboard',label:'Alignment to fretboard diagram:',icons:[ICON_CODES.ALIGN_LEFT,ICON_CODES.ALIGN_HORIZONTAL_CENTER,ICON_CODES.ALIGN_RIGHT]}]" :key="item.id" class="sd-row sd-control-row" style="gap:8px"><div class="sd-row-label" style="width:120px"><span class="sd-label">{{ qtrc('notation',item.label) }}</span></div><div class="sd-row-control" style="width:98px"><div class="sd-flat-radio-group" role="radiogroup" :aria-label="qtrc('notation',item.label)" style="gap:4px"><button v-for="(icon,index) in item.icons" :key="index" type="button" role="radio" class="sd-flat-radio" :aria-checked="style.value(item.id)===[0,2,1][index]" @click="style.setValue(item.id,[0,2,1][index])"><span class="sd-icon" aria-hidden="true">{{ String.fromCodePoint(icon) }}</span></button></div></div></div><label class="sd-checkbox"><input type="checkbox" :checked="style.value('chordAlignmentExcludeModifiers')===true" @change="style.setValue('chordAlignmentExcludeModifiers',!style.value('chordAlignmentExcludeModifiers'))"><span>{{ qtrc('notation/editstyle/chordsymbols','Exclude modifiers from horizontal alignment') }}</span></label></div></fieldset>
    <fieldset class="sd-groupbox" style="min-width:500px"><legend>{{ qtrc('notation/editstyle/chordsymbols','Positioning') }}</legend><div class="sd-column" style="gap:12px"><div v-for="(item,index) in [{id:'harmonyFretDist',label:'Min. space to fretboard diagram:'},{id:'minHarmonyDistance',label:'Min. space to other notation:'},{id:'harmonyHarmonyDistance',label:'Min. space between chord symbols:'}]" :key="item.id" class="sd-row" style="gap:6px"><span class="sd-label">{{ qtrc('notation',item.label) }}</span><ChordNumber :style-model="style" :id="item.id" :label="qtrc('notation',item.label)" :step="0.05" /><button v-if="index===0" type="button" class="sd-flat-button icon-only" :aria-label="qtrc('global','Reset')" @click="['harmonyFretDist','minHarmonyDistance'].forEach(id=>style.resetValue?.(id))"><span class="sd-icon">{{ String.fromCodePoint(ICON_CODES.UNDO) }}</span></button></div></div></fieldset>
    <fieldset class="sd-groupbox" style="min-width:500px"><legend>{{ qtrc('notation/editstyle/chordsymbols','Playback') }}</legend><div class="sd-column" style="gap:12px"><div class="sd-grid" style="grid-template-columns:auto auto 1fr;column-gap:6px;row-gap:12px"><template v-for="(item,i) in [{id:'harmonyVoiceLiteral',label:'Interpretation:',options:['Jazz','Literal']},{id:'harmonyVoicing',label:'Voicing:',options:['Automatic','Root only','Close','Drop two','Six note','Four note','Three note']},{id:'harmonyDuration',label:'Duration:',options:['Until next chord symbol','Until end of measure','Chord/rest duration']}]" :key="item.id"><span class="sd-label">{{ qtrc('notation',item.label) }}</span><select class="sd-dropdown" :aria-label="qtrc('notation',item.label)" :value="Number(style.value(item.id))" @change="style.setValue(item.id,Number(($event.target as HTMLSelectElement).value))"><option v-for="(option,index) in item.options" :key="option" :value="index">{{ qtrc('notation/editstyle/chordsymbols',option) }}</option></select><div v-if="i===0" style="justify-self:end"><button type="button" class="sd-flat-button icon-only" :aria-label="qtrc('global','Reset')" @click="['harmonyVoiceLiteral','harmonyVoicing','harmonyDuration'].forEach(id=>style.resetValue?.(id))"><span class="sd-icon">{{ String.fromCodePoint(ICON_CODES.UNDO) }}</span></button></div><span v-else></span></template></div></div></fieldset>
    <fieldset class="sd-groupbox" style="min-width:500px"><legend>{{ qtrc('notation/editstyle/chordsymbols','Capo') }}</legend><div class="sd-column" style="gap:12px"><div class="sd-row" style="gap:6px"><div class="sd-column" style="gap:0"><div v-for="(label,index) in ['Don’t show chord symbols transposed by capo','Show chord symbols & transposed symbols','Show transposed symbols only']" :key="label" style="height:30px;display:flex;align-items:center"><label class="sd-radio"><input type="radio" name="capo-display" :checked="style.value('displayCapoChords')===index" @change="style.setValue('displayCapoChords',index)"><span>{{ qtrc('notation/editstyle/chordsymbols',label) }}</span></label></div></div><button type="button" class="sd-flat-button icon-only" :aria-label="qtrc('global','Reset')" @click="['displayCapoChords','capoPosition'].forEach(id=>style.resetValue?.(id))"><span class="sd-icon">{{ String.fromCodePoint(ICON_CODES.UNDO) }}</span></button></div><div class="sd-row" :class="{disabled:style.value('displayCapoChords')===0}" style="gap:6px"><span class="sd-label">{{ qtrc('notation','Capo fret position:') }}</span><ChordNumber :style-model="style" id="capoPosition" :label="qtrc('notation','Capo fret position:')" :disabled="style.value('displayCapoChords')===0" :max="11" :step="1" :decimals="0" unit="" /></div></div></fieldset>
